_G.eitri_reload_timer = vim.uv.new_timer(); local t = _G.eitri_reload_timer; _G.eitri_reload_timer:start(1000, 1000, function() vim.schedule(function() local seen = {} for _, w in ipairs(vim.api.nvim_list_wins()) do pcall(function() if not vim.api.nvim_win_is_valid(w) then return end local b = vim.api.nvim_win_get_buf(w) if seen[b] or not vim.api.nvim_buf_is_valid(b) then return end seen[b] = true if vim.bo[b].modified then return end local ar = vim.api.nvim_get_option_value('autoread', { buf = b }) if ar == nil or ar == -1 then ar = vim.go.autoread end if ar ~= true and ar ~= 1 then return end vim.cmd('checktime ' .. b) end) end end) end); return function() if not t:is_closing() then t:stop(); t:close() end; if _G.eitri_reload_timer == t then _G.eitri_reload_timer = nil end end